:where([data-moru-registry]) .ui-drawer {
  box-sizing: border-box;
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-label-size, 13px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.5);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.015em);
  color: var(--ui-text, #171717);
  overflow-wrap: anywhere;
  --ui-navigation-height: var(--ui-control-height-md, 40px);
  --ui-navigation-padding: var(--ui-control-padding-x-md, 14px);
  --ui-navigation-icon: var(--ui-icon-size-md, 16px);
  --ui-navigation-close-size: var(--ui-control-height-sm, 32px);
}
:where([data-moru-registry]) [data-size='sm'].ui-drawer {
  --ui-navigation-height: var(--ui-control-height-sm, 32px);
  --ui-navigation-padding: var(--ui-control-padding-x-sm, 10px);
  --ui-navigation-icon: var(--ui-icon-size-sm, 14px);
  font-size: var(--ui-type-caption-size, 12px);
}
:where([data-moru-registry]) [data-size='lg'].ui-drawer {
  --ui-navigation-height: var(--ui-control-height-lg, 48px);
  --ui-navigation-padding: var(--ui-control-padding-x-lg, 18px);
  --ui-navigation-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-drawer {
  --ui-drawer-handle-size: max(32px, var(--ui-control-height-sm, 32px));
  position: fixed;
  z-index: 71;
  inset-inline: 0;
  inset-block-end: 0;
  display: block;
  overflow-y: auto;
  overscroll-behavior: contain;
  width: min(640px, 100%);
  max-height: calc(100dvh - max(16px, env(safe-area-inset-top)));
  margin-inline: auto;
  padding: 0 max(var(--ui-card-padding, 24px), env(safe-area-inset-right))
    max(var(--ui-card-padding, 24px), env(safe-area-inset-bottom))
    max(var(--ui-card-padding, 24px), env(safe-area-inset-left));
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-bottom: 0;
  border-radius: var(--ui-radius, 6px) var(--ui-radius, 6px) 0 0;
  background: var(--ui-surface, #fff);
  box-shadow: var(--ui-shadow, 0 -8px 28px #00000016);
  transform: translateY(var(--ui-drawer-drag, 0));
  transition:
    transform var(--ui-duration, 160ms),
    opacity var(--ui-duration, 160ms);
}
:where([data-moru-registry]) .ui-drawer[data-starting-style],
:where([data-moru-registry]) .ui-drawer[data-ending-style] {
  transform: translateY(100%);
  opacity: 0.5;
}
:where([data-moru-registry]) .ui-drawer[data-dragging] {
  transition: none;
}
:where([data-moru-registry]) .ui-drawer-handle {
  display: grid;
  box-sizing: border-box;
  place-items: center;
  width: min(160px, 55%);
  height: var(--ui-drawer-handle-size);
  min-height: var(--ui-drawer-handle-size);
  padding: var(--ui-space, 4px);
  margin: 0 auto;
  border: 0;
  border-radius: 0 0 8px 8px;
  background: transparent;
  cursor: grab;
  touch-action: none;
  user-select: none;
  flex: none;
}
:where([data-moru-registry]) .ui-drawer-handle:active {
  cursor: grabbing;
}
:where([data-moru-registry]) .ui-drawer-handle > span {
  display: block;
  width: 40px;
  height: 4px;
  border-radius: 4px;
  background: var(--ui-border, #d4d4d8);
}
:where([data-moru-registry]) .ui-drawer-header {
  box-sizing: border-box;
  min-height: calc(
    var(--ui-navigation-close-size) + var(--ui-field-gap, 8px) + var(--ui-form-gap, 20px)
  );
  padding-inline-end: calc(var(--ui-navigation-close-size) + var(--ui-control-gap, 8px));
  padding-block: var(--ui-field-gap, 8px) var(--ui-form-gap, 20px);
  flex: none;
}
/* Scroll the complete drawer so tall headers/footers cannot squeeze the form to zero. */
:where([data-moru-registry]) .ui-drawer-content {
  min-width: 0;
  overflow: visible;
}
:where([data-moru-registry]) .ui-drawer-content > :first-child {
  margin-block-start: 0;
}
:where([data-moru-registry]) .ui-drawer-content > :last-child {
  margin-block-end: 0;
}
:where([data-moru-registry]) .ui-drawer-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--ui-field-gap, 8px);
  padding-top: var(--ui-form-gap, 20px);
}
:where([data-moru-registry]) .ui-drawer-footer > :is(button, .ui-button) {
  min-width: 0;
  max-width: 100%;
  height: auto;
  white-space: normal;
  overflow-wrap: anywhere;
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-drawer {
    transition: none;
  }
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-drawer {
    --ui-navigation-close-size: max(44px, var(--ui-control-height-sm, 32px));
  }
  :where([data-moru-registry]) .ui-drawer {
    --ui-drawer-handle-size: max(44px, var(--ui-control-height-sm, 32px));
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import {
  useEffect,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type CSSProperties,
  type ReactElement,
  type ReactNode,
} from 'react'
import { Dialog as BaseDialog } from '@base-ui/react/dialog'
import { X } from 'lucide-react'
import { cn } from './_lib/cn'
import { shouldDismissDrawer, shouldSuppressDrawerClick } from './drawer-utils'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './navigation-shared.css'
import './drawer.css'

export interface DrawerProps {
  trigger?: ReactElement
  title: string
  description?: string
  children?: ReactNode
  footer?: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  size?: 'sm' | 'md' | 'lg'
  className?: string
  initialFocus?: ComponentPropsWithoutRef<typeof BaseDialog.Popup>['initialFocus']
  finalFocus?: ComponentPropsWithoutRef<typeof BaseDialog.Popup>['finalFocus']
}
/** A bottom modal with a keyboard-operable pull handle and downward pointer dismissal. */
export function Drawer({
  trigger,
  title,
  description,
  children,
  footer,
  open,
  defaultOpen = false,
  onOpenChange,
  disabled,
  size = 'md',
  className,
  initialFocus,
  finalFocus,
}: DrawerProps) {
  const { t } = useI18n()

  const portalContainer = useThemePortalContainer()
  const [localOpen, setLocalOpen] = useState(defaultOpen)
  const [drag, setDrag] = useState(0)
  const gesture = useRef<{ y: number; started: number; pointerId: number } | null>(null)
  const suppressClick = useRef(false)
  const isOpen = open ?? localOpen
  useEffect(() => {
    if (isOpen) return
    // A controlled caller may close without going through changeOpen.
    gesture.current = null
    suppressClick.current = false
    setDrag(0)
  }, [isOpen])
  function changeOpen(next: boolean) {
    if (next && disabled) return
    gesture.current = null
    setDrag(0)
    if (open === undefined) setLocalOpen(next)
    onOpenChange?.(next)
  }
  return (
    <BaseDialog.Root open={isOpen} onOpenChange={changeOpen}>
      {trigger ? <BaseDialog.Trigger render={trigger} disabled={disabled} /> : null}
      <OverlayPortal portal={BaseDialog.Portal} kind="modal" container={portalContainer}>
        <BaseDialog.Backdrop className="ui-navigation-backdrop" />
        <BaseDialog.Popup
          className={cn('ui-drawer', className)}
          data-size={size}
          data-dragging={gesture.current ? '' : undefined}
          style={{ '--ui-drawer-drag': `${drag}px` } as CSSProperties}
          initialFocus={initialFocus}
          finalFocus={finalFocus}
        >
          <button
            className="ui-drawer-handle"
            type="button"
            aria-label={t('아래로 끌거나 눌러 닫기')}
            onClick={(event) => {
              const suppress = shouldSuppressDrawerClick(suppressClick.current, event.detail)
              suppressClick.current = false
              if (!suppress) changeOpen(false)
            }}
            onPointerDown={(event) => {
              if (event.button !== 0 || !event.isPrimary) return
              gesture.current = {
                y: event.clientY,
                started: event.timeStamp,
                pointerId: event.pointerId,
              }
              suppressClick.current = false
              event.currentTarget.setPointerCapture(event.pointerId)
            }}
            onPointerMove={(event) => {
              if (gesture.current?.pointerId !== event.pointerId) return
              const distance = Math.max(0, event.clientY - gesture.current.y)
              if (distance > 5) suppressClick.current = true
              setDrag(distance)
            }}
            onPointerUp={(event) => {
              const current = gesture.current
              if (!current || current.pointerId !== event.pointerId) return
              const distance = Math.max(0, event.clientY - current.y)
              const dismiss = shouldDismissDrawer(distance, event.timeStamp - current.started)
              gesture.current = null
              setDrag(0)
              if (dismiss) changeOpen(false)
            }}
            onPointerCancel={() => {
              gesture.current = null
              setDrag(0)
              suppressClick.current = false
            }}
            onLostPointerCapture={() => {
              gesture.current = null
              setDrag(0)
            }}
          >
            <span aria-hidden="true" />
          </button>
          <header className="ui-drawer-header">
            <BaseDialog.Title className="ui-navigation-heading">{title}</BaseDialog.Title>
            {description ? (
              <BaseDialog.Description className="ui-navigation-description">
                {description}
              </BaseDialog.Description>
            ) : null}
          </header>
          <BaseDialog.Close className="ui-navigation-close" aria-label={t('드로어 닫기')}>
            <X size={18} aria-hidden="true" />
          </BaseDialog.Close>
          <div className="ui-drawer-content">{children}</div>
          {footer ? <footer className="ui-drawer-footer">{footer}</footer> : null}
        </BaseDialog.Popup>
      </OverlayPortal>
    </BaseDialog.Root>
  )
}
